import sys
import re

class DinnerPlates:
    def __init__(self, capacity):
        self.cap = capacity
        self.stacks = []

    def push(self, val):
        for s in self.stacks:
            if len(s) < self.cap:
                s.append(val)
                return
        self.stacks.append([val])

    def pop(self):
        while self.stacks and not self.stacks[-1]:
            self.stacks.pop()
        if not self.stacks:
            return -1
        return self.stacks[-1].pop()

    def popAtStack(self, i):
        if i < len(self.stacks) and self.stacks[i]:
            return self.stacks[i].pop()
        return -1


