import java.util.*;

class DinnerPlates {

    int cap;
    List<Stack<Integer>> stacks;

    DinnerPlates(int capacity) {
        cap = capacity;
        stacks = new ArrayList<>();
    }

    void push(int val) {
        for (Stack<Integer> s : stacks) {
            if (s.size() < cap) {
                s.push(val);
                return;
            }
        }
        Stack<Integer> ns = new Stack<>();
        ns.push(val);
        stacks.add(ns);
    }

    int pop() {
        while (!stacks.isEmpty() && stacks.get(stacks.size() - 1).isEmpty())
            stacks.remove(stacks.size() - 1);

        if (stacks.isEmpty()) return -1;

        return stacks.get(stacks.size() - 1).pop();
    }

    int popAtStack(int i) {
        if (i < stacks.size() && !stacks.get(i).isEmpty())
            return stacks.get(i).pop();
        return -1;
    }
}

public class Solution {

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);
        String input = sc.nextLine();

        int capacity = Integer.parseInt(input.split("capacity=")[1].split(" ")[0]);

        String opsPart = input.substring(input.indexOf("operations=") + 11);
        opsPart = opsPart.substring(2, opsPart.length() - 2);

        String[] ops = opsPart.split("\\],\\[");

        DinnerPlates dp = new DinnerPlates(capacity);

        int result = -1;

        for (String op : ops) {

            String[] parts = op.split(",");

            if (parts[0].equals("push")) {
                dp.push(Integer.parseInt(parts[1]));
            }
            else if (parts[0].equals("pop")) {
                result = dp.pop();
            }
            else if (parts[0].equals("popAtStack")) {
                result = dp.popAtStack(Integer.parseInt(parts[1]));
            }
        }

        System.out.println(result);
    }
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_STACKS 1000
#define MAX_CAP 100

int stacks[MAX_STACKS][MAX_CAP];
int top[MAX_STACKS];
int cap;
int stack_count = 0;

void push(int val) {
    for (int i = 0; i < stack_count; i++) {
        if (top[i] < cap) {
            stacks[i][top[i]++] = val;
            return;
        }
    }

    stacks[stack_count][0] = val;
    top[stack_count] = 1;
    stack_count++;
}

int pop() {

    while (stack_count > 0 && top[stack_count - 1] == 0)
        stack_count--;

    if (stack_count == 0)
        return -1;

    return stacks[stack_count - 1][--top[stack_count - 1]];
}

int popAtStack(int idx) {

    if (idx < stack_count && top[idx] > 0) {
        return stacks[idx][--top[idx]];
    }

    return -1;
}

int main() {

    char input[10000];
    fgets(input, sizeof(input), stdin);

    sscanf(input, "capacity=%d", &cap);

    for (int i = 0; i < MAX_STACKS; i++)
        top[i] = 0;

    char *p = input;
    int result = -1;

    while ((p = strchr(p, '['))) {

        char op[50];
        int val;

        if (sscanf(p, "[push,%d]", &val) == 1) {
            push(val);
        }
        else if (strncmp(p, "[pop]", 5) == 0) {
            result = pop();
        }
        else if (sscanf(p, "[popAtStack,%d]", &val) == 1) {
            result = popAtStack(val);
        }

        p++;
    }

    printf("%d", result);
