class MaxStack {

    Stack<Integer> stack = new Stack<>();

    void push(int x){
        stack.push(x);
    }

    int pop(){
        return stack.pop();
    }

    int top(){
        return stack.peek();
    }

    int peekMax(){
        return Collections.max(stack);
    }

    int popMax(){

        int max = Collections.max(stack);
        Stack<Integer> buffer = new Stack<>();

        while(stack.peek() != max)
            buffer.push(stack.pop());

        stack.pop();

        while(!buffer.isEmpty())
            stack.push(buffer.pop());

        return max;
    }
}

