#include <ctype.h>

int main() {

    char s[100000];
    scanf("%s", s);

    int stack[100000];
    int top = -1;

    int num = 0;
    char sign = '+';

    int len = strlen(s);

    for (int i = 0; i <= len; i++) {

        char c = (i == len) ? '+' : s[i];

        if (isdigit(c)) {
            num = num * 10 + (c - '0');
        }

        if (!isdigit(c) || i == len) {

            if (sign == '+') stack[++top] = num;
            else if (sign == '-') stack[++top] = -num;
            else if (sign == '*') stack[top] = stack[top] * num;
            else if (sign == '/') stack[top] = stack[top] / num;

            sign = c;
            num = 0;
        }
    }

    int result = 0;

    for (int i = 0; i <= top; i++) {
        result += stack[i];
    }

    printf("%d", result);
}

#include <bits/stdc++.h>
using namespace std;

int main() {

    string s;
    cin >> s;

    stack<int> st;

    int num = 0;
    char sign = '+';

    for (int i = 0; i <= s.size(); i++) {

        char c = (i == s.size()) ? '+' : s[i];

        if (isdigit(c)) {
            num = num * 10 + (c - '0');
        }

        if (!isdigit(c) || i == s.size()) {

            if (sign == '+') st.push(num);
            else if (sign == '-') st.push(-num);
            else if (sign == '*') {
                int v = st.top(); st.pop();
                st.push(v * num);
            }
            else if (sign == '/') {
                int v = st.top(); st.pop();
                st.push(v / num);
            }

            sign = c;
            num = 0;
        }
    }

    int result = 0;

    while (!st.empty()) {
        result += st.top();
        st.pop();
    }

    cout << result;
}
